const JS = `
const sections = ['home', 'framework', 'build', 'run', 'smart', 'components', 'integrations', 'research', 'examples', 'community', 'provenance'];

  // ───── Mobile drawer ─────
  function isMobile() { return window.innerWidth <= 768; }

  function toggleSidebar() {
    const sb = document.getElementById('sidebar');
    const bd = document.getElementById('sidebar-backdrop');
    if (!sb) return;
    const willOpen = !sb.classList.contains('open');
    sb.classList.toggle('open', willOpen);
    if (bd) bd.classList.toggle('open', willOpen);
    document.body.style.overflow = (willOpen && isMobile()) ? 'hidden' : '';
  }

  function closeSidebarIfMobile() {
    if (!isMobile()) return;
    const sb = document.getElementById('sidebar');
    const bd = document.getElementById('sidebar-backdrop');
    if (sb && sb.classList.contains('open')) {
      sb.classList.remove('open');
      if (bd) bd.classList.remove('open');
      document.body.style.overflow = '';
    }
  }

  // ESC closes the drawer
  window.addEventListener('keydown', (e) => {
    if (e.key === 'Escape') closeSidebarIfMobile();
  });

  // Resize past the breakpoint resets drawer state
  window.addEventListener('resize', () => {
    if (!isMobile()) {
      const sb = document.getElementById('sidebar');
      const bd = document.getElementById('sidebar-backdrop');
      if (sb) sb.classList.remove('open');
      if (bd) bd.classList.remove('open');
      document.body.style.overflow = '';
    }
  });

  // Continuum Framework owns all of these areas; Aura and Provenance are standalone products.
  const FRAMEWORK_AREAS = ['framework', 'build', 'run', 'components', 'integrations', 'research', 'examples', 'community'];

  function showSection(name) {
    // Hide every section + its sidebar, and the framework area-nav
    sections.forEach(s => {
      const sec = document.getElementById('sec-' + s);
      if (sec) sec.classList.remove('active');
      const sb = document.getElementById('sb-' + s);
      if (sb) sb.style.display = 'none';
    });
    const areaNav = document.getElementById('sb-framework-areas');
    if (areaNav) areaNav.style.display = 'none';

    // Show the target section + its sub-section sidebar
    const sec = document.getElementById('sec-' + name);
    if (sec) sec.classList.add('active');
    const sb = document.getElementById('sb-' + name);
    if (sb) sb.style.display = 'block';

    // Framework areas share one persistent area-nav (the framework's sub-sections)
    if (areaNav && FRAMEWORK_AREAS.includes(name)) {
      areaNav.style.display = 'block';
      areaNav.querySelectorAll('.area-link').forEach(l =>
        l.classList.toggle('active', l.dataset.area === name));
    }

    // Product switcher follows the PRODUCT: Framework=all areas, Aura=smart, Provenance=provenance
    const currentProduct = name === 'smart' ? 'smart' : name === 'provenance' ? 'provenance' : (FRAMEWORK_AREAS.includes(name) ? 'framework' : null);
    document.querySelectorAll('.product-tab').forEach((t) => {
      const on = t.dataset.section === currentProduct;
      t.classList.toggle('active', on);
      if (on) t.setAttribute('aria-current', 'page'); else t.removeAttribute('aria-current');
    });

    // Reset scroll + re-arm scroll-reveal for the newly shown content
    document.getElementById('main').scrollTop = 0;
    window.scrollTo(0, 0);
    if (window.armReveal) window.armReveal();

    // Activate the first sub-section link
    const links = document.querySelectorAll('#sb-' + name + ' .sidebar-link');
    if (links.length > 0) {
      links.forEach(l => l.classList.remove('active'));
      links[0].classList.add('active');
    }

    closeSidebarIfMobile();
  }

  // Parse the exact anchor id out of a sidebar link's onclick (avoids substring prefix bugs)
  function linkAnchor(l) {
    const m = (l.getAttribute('onclick') || '').match(/scrollToAnchor\\('([^']+)'\\)/);
    return m ? m[1] : null;
  }

  function scrollToAnchor(anchorId) {
    const el = document.getElementById(anchorId);
    if (el) {
      const y = el.getBoundingClientRect().top + window.scrollY - 70;
      window.scrollTo({ top: y, behavior: 'smooth' });
    }
    // Update sidebar active (exact match; leave area-nav links, which use showSection, untouched)
    document.querySelectorAll('.sidebar-link').forEach(l => {
      const a = linkAnchor(l);
      if (a !== null) l.classList.toggle('active', a === anchorId);
    });

    closeSidebarIfMobile();
  }

  function copyCode(btn) {
    // after DOM rewrite, btn is sibling of pre inside .code-wrapper
    const wrapper = btn.closest('.code-wrapper') || btn.parentElement;
    const pre = wrapper.querySelector('pre') || btn.parentElement;
    const text = pre.innerText.trim();
    if (!navigator.clipboard) return;
    navigator.clipboard.writeText(text).then(() => {
      btn.textContent = 'copied!';
      setTimeout(() => btn.textContent = 'copy', 1500);
    }).catch(() => {});
  }

  // Scrollspy, update sidebar as user scrolls
  window.addEventListener('scroll', () => {
    // Reading-progress bar
    const bar = document.getElementById('read-progress');
    if (bar) {
      const doc = document.documentElement;
      const max = (doc.scrollHeight - window.innerHeight) || 1;
      bar.style.width = Math.max(0, Math.min(100, (window.scrollY / max) * 100)) + '%';
    }
    const anchors = document.querySelectorAll('.page-section.active .anchor');
    let current = null;
    anchors.forEach(a => {
      if (window.scrollY >= a.offsetTop - 90) current = a.id;
    });
    if (current) {
      document.querySelectorAll('.sidebar-link').forEach(l => {
        const a = linkAnchor(l);
        if (a !== null) l.classList.toggle('active', a === current);
      });
    }
  });

  // Suite cards (role=button), Enter/Space activate, like a real button
  document.querySelectorAll('.suite-card').forEach(card => {
    card.addEventListener('keydown', e => {
      if (e.key === 'Enter' || e.key === ' ') { e.preventDefault(); card.click(); }
    });
  });

  // href-less onclick anchors (sidebar TOC + inline cross-links), make them keyboard-operable
  document.querySelectorAll('a[onclick]:not([href])').forEach(a => {
    if (!a.hasAttribute('tabindex')) a.setAttribute('tabindex', '0');
    if (!a.hasAttribute('role')) a.setAttribute('role', 'link');
    a.addEventListener('keydown', e => {
      if (e.key === 'Enter' || e.key === ' ') { e.preventDefault(); a.click(); }
    });
  });

  // ───── Minimal constellation background (vanilla canvas, monochrome) ─────
  (function constellation() {
    const canvas = document.getElementById('bg-canvas');
    if (!canvas) return;
    if (window.matchMedia && window.matchMedia('(prefers-reduced-motion: reduce)').matches) return;
    const ctx = canvas.getContext('2d');
    let w, h, dpr, pts = [], raf, t;
    function size() {
      dpr = Math.min(window.devicePixelRatio || 1, 2);
      w = canvas.width = Math.floor(innerWidth * dpr);
      h = canvas.height = Math.floor(innerHeight * dpr);
      canvas.style.width = innerWidth + 'px';
      canvas.style.height = innerHeight + 'px';
      const count = Math.max(18, Math.min(60, Math.round(innerWidth * innerHeight / 28000)));
      pts = Array.from({ length: count }, () => ({
        x: Math.random() * w, y: Math.random() * h,
        vx: (Math.random() - 0.5) * 0.16 * dpr,
        vy: (Math.random() - 0.5) * 0.16 * dpr,
        r: (Math.random() * 1.1 + 0.6) * dpr,
      }));
    }
    function frame() {
      ctx.clearRect(0, 0, w, h);
      const link = 132 * dpr;
      for (let i = 0; i < pts.length; i++) {
        const p = pts[i];
        p.x += p.vx; p.y += p.vy;
        if (p.x < 0 || p.x > w) p.vx *= -1;
        if (p.y < 0 || p.y > h) p.vy *= -1;
        ctx.beginPath(); ctx.arc(p.x, p.y, p.r, 0, Math.PI * 2);
        ctx.fillStyle = 'rgba(24,28,38,0.28)'; ctx.fill();
        for (let j = i + 1; j < pts.length; j++) {
          const q = pts[j], dx = p.x - q.x, dy = p.y - q.y, d = Math.hypot(dx, dy);
          if (d < link) {
            ctx.beginPath(); ctx.moveTo(p.x, p.y); ctx.lineTo(q.x, q.y);
            ctx.strokeStyle = 'rgba(48,56,74,' + (0.11 * (1 - d / link)).toFixed(3) + ')';
            ctx.lineWidth = dpr * 0.6; ctx.stroke();
          }
        }
      }
      raf = requestAnimationFrame(frame);
    }
    size(); frame();
    window.addEventListener('resize', () => { clearTimeout(t); t = setTimeout(size, 200); });
  })();

  // ───── Scroll reveal (IntersectionObserver; classes added by JS so no-JS stays visible) ─────
  (function () {
    if ((window.matchMedia && window.matchMedia('(prefers-reduced-motion: reduce)').matches) || !('IntersectionObserver' in window)) {
      window.armReveal = function () {}; return;
    }
    const SEL = 'h2, .cards, .suite, .code-wrapper, .callout, table, .steps, .workflow-grid, .cs-pills, .proprietary, .ph-meta, .stats, .flow, .cta-band';
    const io = new IntersectionObserver((entries) => {
      entries.forEach(e => { if (e.isIntersecting) { e.target.classList.add('in'); io.unobserve(e.target); } });
    }, { rootMargin: '0px 0px -7% 0px', threshold: 0.05 });
    window.armReveal = function () {
      const active = document.querySelector('.page-section.active');
      if (!active) return;
      active.querySelectorAll(SEL).forEach(el => {
        el.classList.add('reveal');
        if (el.getBoundingClientRect().top < innerHeight * 0.92) el.classList.add('in'); // in view: show now
        else io.observe(el); // below the fold: fade up on scroll
      });
    };
  })();

  // Initialise on the Continuum Framework / Overview view
  showSection('home');
`

interface Props {
    logo?: string
    wordmark?: string
    byline?: string
    version?: string
    fontInter?: string
    fontGeist?: string
    fontJetBrains?: string
    fontSpaceMono?: string
    width?: number | string
    height?: number | string
}

function buildFontCss(p: Props) {
    const face = (family: string, url?: string) =>
        url
            ? `@font-face { font-family: '${family}'; src: url('${url}'); font-weight: 400 800; font-display: swap; font-style: normal; }`
            : ""
    return [
        face("Inter", p.fontInter),
        face("Geist", p.fontGeist),
        face("JetBrains Mono", p.fontJetBrains),
        face("Space Mono", p.fontSpaceMono),
    ].join("\n")
}

export default function ContinuumDocs(props: Props) {
    const {
        logo = "",
        wordmark = "",
        byline = "",
        version = "v0.2.0",
        width = "100%",
        height,
    } = props
    const rootRef = React.useRef<HTMLDivElement>(null)

    // Empty brand props collapse to nothing — when all three are empty
    // we drop the entire <a class="nav-logo"> wrapper so no gap/margin
    // is left behind in the topnav layout.
    const html = React.useMemo(() => {
        let h = BODY
        const hasBrand = !!(logo || wordmark || byline)

        if (!hasBrand) {
            // Remove the whole nav-logo anchor (img + wordmark + byline + wrapper)
            h = h.replace(/<a class="nav-logo"[\s\S]*?<\/a>/m, "")
        } else {
            if (logo) {
                h = h.replaceAll("__LOGO__", logo)
            } else {
                h = h.replace(/<img class="mark"[^>]*\/>/g, "")
            }
            if (wordmark) {
                h = h.replaceAll("__WORDMARK__", wordmark)
            } else {
                h = h.replace(/<span class="wordmark">__WORDMARK__<\/span>/g, "")
            }
            if (byline) {
                h = h.replaceAll("__BYLINE__", byline)
            } else {
                h = h.replace(/<span class="byline">__BYLINE__<\/span>/g, "")
            }
            // Drop the inner .text wrapper if both wordmark and byline are empty
            if (!wordmark && !byline) {
                h = h.replace(/<span class="text">[\s\S]*?<\/span>/m, "")
            }
        }

        h = h.replaceAll("__VERSION__", version || "")
        return h
    }, [logo, wordmark, byline, version])

    // Watch the component's measured width and toggle breakpoint classes
    // on the root. This drives all responsive styles — we don't rely on
    // @media or @container queries because Framer's runtime doesn't
    // reliably propagate either down to the component frame size.
    React.useEffect(() => {
        if (!rootRef.current) return
        const el = rootRef.current
        const apply = (w: number) => {
            el.classList.toggle("cn-tablet", w <= 1024)
            el.classList.toggle("cn-mobile", w <= 768)
            el.classList.toggle("cn-small", w <= 480)
        }
        apply(el.getBoundingClientRect().width)
        const ro = new ResizeObserver((entries) => {
            for (const e of entries) apply(e.contentRect.width)
        })
        ro.observe(el)
        return () => ro.disconnect()
    }, [])

    React.useEffect(() => {
        // Re-bind the inline JS so onclick="..." attributes in the HTML
        // resolve to globally-visible functions on window.
        //
        // IMPORTANT: the wrapper string below is evaluated as plain
        // JavaScript at runtime via new Function(). It MUST NOT contain
        // any TypeScript syntax (e.g. `as any`) — the TS compiler can't
        // strip casts from inside a template literal, and the resulting
        // raw text would be a SyntaxError to the JS parser.
        try {
            const w = window as unknown as Record<string, unknown>
            const wrapper = `
                (function (w) {
                    ${JS}
                    if (typeof showSection === 'function') w.showSection = showSection;
                    if (typeof scrollToAnchor === 'function') w.scrollToAnchor = scrollToAnchor;
                    if (typeof copyCode === 'function') w.copyCode = copyCode;
                    if (typeof toggleSidebar === 'function') w.toggleSidebar = toggleSidebar;
                    if (typeof closeSidebarIfMobile === 'function') w.closeSidebarIfMobile = closeSidebarIfMobile;
                    if (typeof isMobile === 'function') w.isMobile = isMobile;
                })(window);
            `
            void w // silence unused-warning in case the linter checks
            // eslint-disable-next-line no-new-func
            new Function(wrapper)()
        } catch (e) {
            // eslint-disable-next-line no-console
            console.error("ContinuumDocs: failed to bind inline JS", e)
        }
    }, [])

    // NOTE: no `overflow: auto` on the root — the inline JS uses
    // window.scrollY for scrollspy, which only works when the page
    // (not a nested div) is the scroller. Let the component grow to
    // its natural height; Framer's page handles scrolling.
    return (
        <div
            ref={rootRef}
            style={{
                width,
                ...(height !== undefined ? { height } : null),
                background: "#fff",
                color: "#0a0a0a",
            }}
        >
            <style dangerouslySetInnerHTML={{ __html: buildFontCss(props) + "\n" + CSS }} />
            <div dangerouslySetInnerHTML={{ __html: html }} />
        </div>
    )
}

